select 
from approval_template


        and business_code = #{businessCode}


        and template_name like concat('%', #{templateName}, '%')


        and business_source = #{businessSource}


        and engine_mode = #{engineMode}


        and template_status = #{templateStatus}


order by business_source, template_id

